style.css:
/* Указываем браузеру, что для флагов нужно приоритетно использовать Noto */
@font-face {
  font-family: "EmojiFix";
  src: local("Noto Color Emoji");
  /* Этот диапазон отвечает именно за флаги стран */
  unicode-range: U+1F1E6-1F1FF;
}

/* Применяем это ко всем элементам на всех сайтах */
html, body, span, div, a, p {
  font-family: "EmojiFix", system-ui, -apple-system, sans-serif !important;
}
